using System.Text;

using PrintDeck.Application.Files;
using PrintDeck.Domain.Files;

namespace PrintDeck.Application.Tests.Files;

public class GcodeAnalyzerTests
{
	private static Task<GcodeAnalysis> Analyze(string gcode) =>
		GcodeAnalyzer.AnalyzeAsync(new MemoryStream(Encoding.UTF8.GetBytes(gcode)), TestContext.Current.CancellationToken);

	public class SlicerMetadata
	{
		[Fact]
		public async Task Reads_orca_metadata()
		{
			GcodeAnalysis a = await Analyze("""
				; generated by OrcaSlicer 2.3.0 on 2026-11-14
				; total layer number: 42
				; model printing time: 1h 2m 3s; total estimated time: 1h 10m 5s
				G28
				;LAYER_CHANGE
				G1 X10 E1
				; filament used [mm] = 1234.5
				""");
			Assert.Equal("OrcaSlicer", a.Slicer);
			Assert.Equal(new TimeSpan(1, 10, 5), a.EstimatedPrintTime);
			Assert.Equal(42, a.LayerCount);
			Assert.Equal(1234.5, a.FilamentMillimeters);
			Assert.Equal(2, a.CommandCount);
		}

		[Fact]
		public async Task Reads_prusaslicer_metadata()
		{
			GcodeAnalysis a = await Analyze("""
				; generated by PrusaSlicer 2.8.1+linux-x64-GTK3 on 2026-11-14 at 10:00:00 UTC
				G28
				; filament used [mm] = 100.5, 200
				; estimated printing time (normal mode) = 1d 2h 3m 4s
				""");
			Assert.Equal("PrusaSlicer", a.Slicer);
			Assert.Equal(new TimeSpan(1, 2, 3, 4), a.EstimatedPrintTime);
			Assert.Equal(300.5, a.FilamentMillimeters); // summed over extruders
		}

		[Fact]
		public async Task Reads_cura_metadata()
		{
			GcodeAnalysis a = await Analyze(";FLAVOR:Marlin\n;TIME:3600\n;Filament used: 2.5m\n;LAYER_COUNT:10\n;Generated with Cura_SteamEngine 5.8\nG28\n");
			Assert.Equal(TimeSpan.FromHours(1), a.EstimatedPrintTime);
			Assert.Equal(2500, a.FilamentMillimeters);
			Assert.Equal(10, a.LayerCount);
			Assert.Equal("Cura_SteamEngine", a.Slicer);
		}

		[Fact]
		public async Task Counts_layer_markers_when_no_layer_count_is_given()
		{
			GcodeAnalysis a = await Analyze(";LAYER:0\nG1 X1\n;LAYER:1\nG1 X2\n;LAYER_CHANGE\nG1 X3\n");
			Assert.Equal(3, a.LayerCount);
		}

		[Fact]
		public async Task Ignores_blank_lines_and_comments_when_counting_commands()
		{
			GcodeAnalysis a = await Analyze("\n; comment\n   \nG28 ; home\nM105\n");
			Assert.Equal(2, a.CommandCount);
		}

		[Fact]
		public async Task Reports_nothing_for_an_empty_file()
		{
			Assert.Equal(new GcodeAnalysis(null, null, null, 0, null), await Analyze(""));
		}

		[Theory]
		[InlineData("1h 2m 3s", 3723)]
		[InlineData("45s", 45)]
		[InlineData("2d 1h", 176400)]
		[InlineData("10m", 600)]
		public void Parses_durations(string text, int seconds) =>
			Assert.Equal(TimeSpan.FromSeconds(seconds), GcodeAnalyzer.ParseDuration(text));

		[Fact]
		public void Duration_without_units_is_unknown() => Assert.Null(GcodeAnalyzer.ParseDuration("soon"));
	}

	public class MoveSimulation
	{
		[Fact]
		public async Task Falls_back_to_simulating_moves()
		{
			// 600 mm at 6000 mm/min = 6 s; 10 mm extruded, relative extrusion
			GcodeAnalysis a = await Analyze("G90\nM83\nG1 F6000\nG1 X300 E5\nG1 X0 E5\n");
			Assert.Equal(6, a.EstimatedPrintTime!.Value.TotalSeconds, 3);
			Assert.Equal(10, a.FilamentMillimeters!.Value, 3);
			Assert.Null(a.Slicer);
		}

		[Fact]
		public async Task Follows_relative_positioning()
		{
			// two 10 mm moves at 600 mm/min = 2 s
			GcodeAnalysis a = await Analyze("G91\nG1 X10 F600\nG1 X10\n");
			Assert.Equal(2, a.EstimatedPrintTime!.Value.TotalSeconds, 3);
		}

		[Fact]
		public async Task G92_resets_absolute_extrusion()
		{
			GcodeAnalysis a = await Analyze("M82\nG1 X10 E5\nG92 E0\nG1 X20 E5\n");
			Assert.Equal(10, a.FilamentMillimeters!.Value, 3);
		}

		[Fact]
		public async Task Retractions_do_not_count_as_filament()
		{
			GcodeAnalysis a = await Analyze("M83\nG1 E-2\nG1 E2\nG1 X10 E1\n");
			Assert.Equal(3, a.FilamentMillimeters!.Value, 3);
		}

		[Fact]
		public async Task Ignores_inline_comments()
		{
			GcodeAnalysis a = await Analyze("G1 X10 F600 ; X999\n");
			Assert.Equal(1, a.EstimatedPrintTime!.Value.TotalSeconds, 3);
		}

		[Fact]
		public async Task Has_no_estimate_without_motion()
		{
			GcodeAnalysis a = await Analyze("M104 S200\nM140 S60\n");
			Assert.Null(a.EstimatedPrintTime);
			Assert.Null(a.FilamentMillimeters);
		}
	}
}
